import java.io.*;import javax.microedition.rms.RecordStore;
final class ShopInventory {
 final PhoneCanvas c;final int[] offline=new int[12],online=new int[12];boolean onlineLoaded;
 ShopInventory(PhoneCanvas owner){c=owner;for(int i=0;i<12;i++)offline[i]=online[i]=1;}
 void load(){try{RecordStore r=RecordStore.openRecordStore("gunny-wardrobe",true);if(r.getNumRecords()>0){DataInputStream in=new DataInputStream(new ByteArrayInputStream(r.getRecord(1)));for(int i=0;i<12;i++){int mask=in.readUnsignedShort();if(mask>1023)throw new IOException();offline[i]=mask;}if(in.available()>=5){c.shoppingMoney=in.readInt();c.wornMask=in.readUnsignedByte();}else c.wornMask=c.customLook?125:3;in.close();}else{c.wornMask=c.customLook?125:3;offline[c.gender*6]|=1<<c.skin;for(int k=0;k<5;k++)offline[c.gender*6+k+1]|=1<<c.look[k];}r.closeRecordStore();save();}catch(Exception ignored){}}
 void save(){if(c.onlineAccount())return;try{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);for(int i=0;i<12;i++)out.writeShort(offline[i]);out.writeInt(c.shoppingMoney);out.writeByte(c.wornMask);out.close();RecordStore r=RecordStore.openRecordStore("gunny-wardrobe",true);byte[] data=b.toByteArray();if(r.getNumRecords()==0)r.addRecord(data,0,data.length);else r.setRecord(1,data,0,data.length);r.closeRecordStore();}catch(Exception ignored){}}
 boolean owns(int kind,int item){if(kind==0)return(c.owned&(1<<item))!=0;if(c.onlineAccount()&&!c.net.shopCap)return true;if(c.onlineAccount()&&!onlineLoaded)return false;return((c.onlineAccount()?online:offline)[c.gender*6+kind-1]&(1<<item))!=0;}
 void read(DataInputStream in)throws IOException{if(!c.net.equipmentCap){c.shoppingMoney=0;c.wornMask=c.customLook?125:3;}if(c.net.equipmentCap){c.shoppingMoney=in.readInt();c.wornMask=in.readUnsignedByte();if(c.shoppingMoney<0||!ItemRules.validMask(c.wornMask))throw new IOException("Sai trang bị");}for(int i=0;i<12;i++){online[i]=in.readUnsignedShort();if(online[i]>1023)throw new IOException("Sai túi đồ");}if(c.net.bagCap&&in.available()>0)c.bagLayout.read(in);if(c.net.expansionCap)c.economy.read(in);onlineLoaded=true;c.loadLook();}
 boolean exchange(int amount){if(c.onlineAccount())return false;if(amount<=0||amount>9999||amount>c.coins/100||c.shoppingMoney>999999-amount){c.message("Không đủ xu hoặc số lượng không hợp lệ");return false;}c.coins-=amount*100;c.shoppingMoney+=amount;save();c.saveSettings();return true;}
 int total(int[] cart){return ShopCatalog.total(c.gender,cart,c.owned,c.onlineAccount()?online:offline);}
 boolean buy(int[] cart){if(c.onlineAccount())return false;int total=total(cart);if(total>c.shoppingMoney){c.message("Chưa đủ tiền mua sắm");return false;}c.shoppingMoney-=total;c.owned|=cart[0];ShopCatalog.grant(c.gender,cart,offline);save();c.saveSettings();c.message("Đã mua đồ vào túi");return true;}
}
